59: static void SendMetaFileToClipboard(HANDLE hmf, int xExt, int yExt)
60: {
61:    GLOBALHANDLE   hGMem;
62:    LPMETAFILEPICT lpMFP;
63: 
64:    hGMem = GlobalAlloc(GHND, (DWORD) sizeof (METAFILEPICT));
65:    lpMFP = (LPMETAFILEPICT) GlobalLock(hGMem);
66: 
67:    lpMFP->mm   = MM_ANISOTROPIC;
68:    lpMFP->xExt = xExt;
69:    lpMFP->yExt = yExt;
70:    lpMFP->hMF  = (HMETAFILE__*)hmf;
71: 
72:    GlobalUnlock(hGMem);
73: 
74:    OpenClipboard(NULL);
75:    SetClipboardData(CF_METAFILEPICT, hGMem);
76:    CloseClipboard();
77: }
