212: char *MyRealloc(char *ptr, unsigned int nold, unsigned int nnew, size_t s)
213: /*
214:  * Allocates the memory pointed to by ptr to hold nnew objects of size s.
215:  * Uses nold to clear any newly allocated memory to '\0' and returns the possibly moved pointer
216:  * to the new memory block.
217:  */
218: {
219:    char *result;
220:    unsigned int i;
221:    static long n_alloc = 0;
222:    static long total_allocation = 0;
223:    
224:    if (ptr == NULL) return MyCalloc(nnew, s);
225: 
226:    result = (char *)realloc((void *)ptr, nnew*s);
227:    if (!IsNULL(result))
228:    {
229:        for (i=nold*s; i<nnew*s; i++) result[i] = '\0';
230:       n_alloc++;
